for _, record in ipairs(RECORDS) do
    Register(record)
end

-- Existing non-gathering BfA materials are source pins, never connected routes.
for _, item in pairs(Items) do
    if item.expansion == "battleForAzeroth" and item.category ~= "Herb" and item.category ~= "Ore" then
        item.isRoute = false
        for _, spot in ipairs(item.spots or {}) do
            spot.isRoute = false
        end
    end
end

local BOUND_SUPPORT_IDS = { 152668, 162460, 162461, 165703, 165948, 167562 }
for _, itemID in ipairs(BOUND_SUPPORT_IDS) do
    local item = Items[itemID]
    if item then
        item.isRoute = false
        item.auctionable = false
        item.category = "Bound Crafting Input"
        item.summary = "Bound support input; cannot be sold on the Auction House. " .. (item.summary or "")
    end
end

-- Hydrocore is a Tidalcore conversion in post-8.1 BfA; the historical shared
-- dungeon spot remains available on the other dungeon reagent records.
if Items[162460] then
    Items[162460].summary = "Bound Hydrocore is obtained by converting Tidalcore with the profession's Aqueous recipe; it no longer directly drops from BfA dungeons."
    Items[162460].spots = {}
end
